/**
 * Documentation Suggestions API
 *
 * Endpoints for managing documentation suggestions generated by the hook system.
 *
 * GET /api/v1/documentation/suggestions - List all suggestions
 * POST /api/v1/documentation/suggestions/:id/approve - Approve a suggestion
 * POST /api/v1/documentation/suggestions/:id/reject - Reject a suggestion
 */

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { DocumentationSuggestionStatus } from '@prisma/client';
import { getCachedSession } from "@/lib/auth/cached-session";

/**
 * GET /api/v1/documentation/suggestions
 *
 * List documentation suggestions with optional filtering
 * Requires admin authentication
 */
export async function GET(request: NextRequest) {
    try {
        // Check authentication
        const session = await getCachedSession();
        if (!session?.user) {
            return NextResponse.json(
                { success: false, error: { code: 'UNAUTHORIZED', message: 'Authentication required' } },
                { status: 401 }
            );
        }

        // Check admin role
        if (session.user.role !== 'ADMIN' && !session.user.isSuperAdmin) {
            return NextResponse.json(
                { success: false, error: { code: 'FORBIDDEN', message: 'Admin access required' } },
                { status: 403 }
            );
        }

        // Parse query parameters
        const { searchParams } = new URL(request.url);
        const status = searchParams.get('status') as 'pending' | 'approved' | 'rejected' | null;
        const targetType = searchParams.get('targetType') as 'tenant' | 'admin' | null;
        const category = searchParams.get('category');
        const limit = parseInt(searchParams.get('limit') || '50');
        const offset = parseInt(searchParams.get('offset') || '0');

        // Build where clause
        const where: any = {};
        if (status) {
            where.status = status.toUpperCase() as DocumentationSuggestionStatus;
        }
        if (targetType) {
            where.targetType = targetType.toUpperCase();
        }
        if (category) {
            where.category = category;
        }

        // Fetch suggestions
        const [suggestions, total] = await Promise.all([
            prisma.documentationSuggestion.findMany({
                where,
                include: {
                    DocumentationDocument: {
                        select: {
                            id: true,
                            title: true,
                            slug: true,
                            type: true,
                            category: true,
                        },
                    },
                },
                orderBy: {
                    createdAt: 'desc',
                },
                take: limit,
                skip: offset,
            }),
            prisma.documentationSuggestion.count({ where }),
        ]);

        return NextResponse.json({
            success: true,
            data: {
                suggestions: suggestions.map(s => ({
                    id: s.id,
                    documentId: s.documentId,
                    document: s.DocumentationDocument ? {
                        id: s.DocumentationDocument.id,
                        title: s.DocumentationDocument.title,
                        slug: s.DocumentationDocument.slug,
                        type: s.DocumentationDocument.type.toLowerCase(),
                        category: s.DocumentationDocument.category,
                    } : null,
                    suggestedTitle: s.suggestedTitle,
                    suggestedContent: s.suggestedContent,
                    targetType: s.targetType.toLowerCase(),
                    category: s.category,
                    status: s.status.toLowerCase(),
                    taskId: s.taskId,
                    createdAt: s.createdAt.toISOString(),
                    reviewedBy: s.reviewedBy,
                    reviewedAt: s.reviewedAt?.toISOString(),
                })),
                pagination: {
                    total,
                    limit,
                    offset,
                    hasMore: offset + limit < total,
                },
            },
            meta: {
                requestId: crypto.randomUUID(),
                timestamp: new Date().toISOString(),
            },
        });
    } catch (error) {
        console.error('[DocumentationSuggestionsAPI] Error listing suggestions:', error);
        return NextResponse.json(
            {
                success: false,
                error: {
                    code: 'INTERNAL_ERROR',
                    message: 'Failed to list documentation suggestions',
                },
            },
            { status: 500 }
        );
    }
}

/**
 * POST /api/v1/documentation/suggestions
 *
 * Create a new documentation suggestion manually
 * Requires admin authentication
 */
export async function POST(request: NextRequest) {
    try {
        // Check authentication
        const session = await getCachedSession();
        if (!session?.user) {
            return NextResponse.json(
                { success: false, error: { code: 'UNAUTHORIZED', message: 'Authentication required' } },
                { status: 401 }
            );
        }

        // Check admin role
        if (session.user.role !== 'ADMIN' && !session.user.isSuperAdmin) {
            return NextResponse.json(
                { success: false, error: { code: 'FORBIDDEN', message: 'Admin access required' } },
                { status: 403 }
            );
        }

        // Parse request body
        const body = await request.json();
        const { documentId, suggestedTitle, suggestedContent, targetType, category, taskId } = body;

        // Validate required fields
        if (!suggestedContent || !targetType || !category) {
            return NextResponse.json(
                {
                    success: false,
                    error: {
                        code: 'VALIDATION_ERROR',
                        message: 'Missing required fields',
                        details: {
                            fields: {
                                suggestedContent: !suggestedContent ? ['Required'] : undefined,
                                targetType: !targetType ? ['Required'] : undefined,
                                category: !category ? ['Required'] : undefined,
                            },
                        },
                    },
                },
                { status: 422 }
            );
        }

        // Validate targetType
        if (!['tenant', 'admin'].includes(targetType)) {
            return NextResponse.json(
                {
                    success: false,
                    error: {
                        code: 'VALIDATION_ERROR',
                        message: 'Invalid targetType',
                        details: {
                            fields: {
                                targetType: ['Must be either "tenant" or "admin"'],
                            },
                        },
                    },
                },
                { status: 422 }
            );
        }

        // Create suggestion
        const suggestion = await prisma.documentationSuggestion.create({
            data: {
                documentId: documentId || null,
                suggestedTitle: suggestedTitle || null,
                suggestedContent,
                targetType: targetType.toUpperCase(),
                category,
                status: DocumentationSuggestionStatus.PENDING,
                taskId: taskId || null,
            },
        });

        return NextResponse.json({
            success: true,
            data: {
                suggestion: {
                    id: suggestion.id,
                    documentId: suggestion.documentId,
                    suggestedTitle: suggestion.suggestedTitle,
                    suggestedContent: suggestion.suggestedContent,
                    targetType: suggestion.targetType.toLowerCase(),
                    category: suggestion.category,
                    status: suggestion.status.toLowerCase(),
                    taskId: suggestion.taskId,
                    createdAt: suggestion.createdAt.toISOString(),
                },
            },
            meta: {
                requestId: crypto.randomUUID(),
                timestamp: new Date().toISOString(),
            },
        }, { status: 201 });
    } catch (error) {
        console.error('[DocumentationSuggestionsAPI] Error creating suggestion:', error);
        return NextResponse.json(
            {
                success: false,
                error: {
                    code: 'INTERNAL_ERROR',
                    message: 'Failed to create documentation suggestion',
                },
            },
            { status: 500 }
        );
    }
}
